     \begin{subfigure}[t]{0.32\textwidth}
         \centering
         \includegraphics[width=\textwidth]{figures/hill_picture.pdf}
         \caption{Hill environment.}
         \label{fig:hill_env}
     \end{subfigure}
     \hfill
     \begin{subfigure}[t]{0.32\textwidth}
