GIN (NO) & $31.9 \pm 1.2$ & $67.7 \pm 1.5$ & $75.4 \pm 2.8$ & $72.3 \pm 1.2$ & $78.4 \pm 0.8$ & $63.1 \pm 0.7$ \\
GIN (LA) & $28.1 \pm 1.6$ & $70.2 \pm 2.1$ & $78.3 \pm 2.1$ & $75.2 \pm 1.3$ & $77.3 \pm 1.1$ & $64.3 \pm 1.0$ \\
GIN (RW) & $28.4 \pm 1.7$ & $71.7 \pm 2.4$ & $78.0 \pm 1.6$ & $74.1 \pm 1.3$ & $78.6 \pm 1.3$ & $64.2 \pm 1.1$ \\
\hline
GAT (NO) & $21.7 \pm 1.5$ & $47.1 \pm 1.6$ & $72.2 \pm 2.1$ & $73.6 \pm 1.4$ & $83.8 \pm 1.1$ & $73.4 \pm 0.9$ \\
GAT (LA) & $25.3 \pm 1.5$ & $52.9 \pm 1.2$ & $74.4 \pm 1.8$ & $74.9 \pm 1.5$ & $85.3 \pm 1.5$ & $75.4 \pm 1.2$ \\
GAT (RW) & $22.0 \pm 1.7$ & $52.1 \pm 0.9$ & $68.5 \pm 2.0$ & $74.1 \pm 1.7$ & $84.2 \pm 1.2$ & $76.1 \pm 1.6$ \\
