    \toprule
    Dataset & \#Train & \#Test & \#Categorical & \#Continuous & Utility  \\
     \midrule
    Bayesian Network & 2000     & 20000    & 3 & 2 & Multi-class classification  \\
    Census \citep{census} & 16000     & 4000    & 9 & 6 & Binary classification  \\
    MIMIC4ED \citep{Xie2022BenchmarkingED} & 353150     &   88287   & 46 & 27 & Regression \\

    \bottomrule
    \end{tabular}}
  \label{tab:dataset}%
